customMethods.script:
if self.view.custom.userAction.canDelete:
	grpInfo = self.view.custom.table.selection.data[0]
	retVal, msg = system.kanoa.quality.config.deleteAlertGroup(grpInfo['alertGroupId'], self.view.custom.security.userId)

	if msg or retVal == 0: system.perspective.sendMessage('showWarningToast', {'message': 'Could not delete this alert group. %s'%msg})
	else: system.perspective.sendMessage('showSuccessfulToast', {'message': 'Alert Group has been deleted'})			

	self.view.custom.table.selection.col = None
	self.view.custom.table.selection.row = None

	self.view.refreshBinding("custom.alertGroups")

return
